LOG_KEPT_MB = 20


def rotate_log(where, most_mb=LOG_KEPT_MB):
    """debug.log to debug.log.1 when it is past `most_mb`; True when it was moved."""
    try:
        if os.path.getsize(where) < most_mb * 1_000_000:
            return False
        os.replace(where, where + ".1")
        return True
    except OSError:
        return False


